INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G8-ALG-022', 'ru-KZ', 'plaintext', 'Упростите дробь (x² − {{a}}²)/(x² − ({{a}}+{{b}})x + {{a}}·{{b}}), учитывая ограничения x ≠ {{a}} и x ≠ {{b}}.', '1.0.0-draft'),
    ('G8-ALG-023', 'ru-KZ', 'plaintext', 'Решите уравнение {{a}}/(x − {{b}}) = {{d}}/(x − {{a}}).', '1.0.0-draft'),
    ('G8-FUN-004', 'ru-KZ', 'plaintext', 'Найдите область определения функции f(x) = √(x − {{a}}). Запишите ответ в виде промежутка.', '1.0.0-draft'),
    ('G8-GEO-008', 'ru-KZ', 'plaintext', 'Основание треугольника равно {{base}}. Найдите длину средней линии, параллельной этому основанию.', '1.0.0-draft'),
    ('G8-GEO-009', 'ru-KZ', 'plaintext', 'Точка на серединном перпендикуляре удалена от одного конца отрезка на {{distance}} единиц. Каково расстояние от этой точки до другого конца?', '1.0.0-draft'),
    ('G8-GEO-010', 'ru-KZ', 'plaintext', 'Центроид делит медиану длиной {{median}} в отношении 2:1. Найдите длину большего отрезка.', '1.0.0-draft'),
    ('G8-GEO-011', 'ru-KZ', 'plaintext', 'Найдите среднее геометрическое чисел {{a}} и {{b}}. Округлите ответ до сотых.', '1.0.0-draft'),
    ('G8-GEO-012', 'ru-KZ', 'plaintext', 'Катеты прямоугольного треугольника равны {{a}} и {{b}}. Найдите гипотенузу и округлите ответ до сотых.', '1.0.0-draft'),
    ('G8-GEO-013', 'ru-KZ', 'plaintext', 'В прямоугольном треугольнике с углами 45°, 45° и 90° катет равен {{a}}. Найдите гипотенузу и округлите ответ до сотых.', '1.0.0-draft'),
    ('G8-GEO-014', 'ru-KZ', 'plaintext', 'В прямоугольном треугольнике с углами 30°, 60° и 90° меньший катет равен {{a}}. Найдите гипотенузу.', '1.0.0-draft'),
    ('G8-GEO-015', 'ru-KZ', 'plaintext', 'В прямоугольном треугольнике угол равен {{angle}}°, а прилежащий катет — {{adjacent}}. Найдите противолежащий катет и округлите ответ до сотых.', '1.0.0-draft')
